```json
{
  "root_causes": [
    {
      "service": "geo",
      "fault_kind": "container_cpu_saturated",
      "evidence": [
        {"kind": "metric", "sql": "SELECT 'abn' AS p, ROUND(AVG(value),3) AS avg_cpu_cores, ROUND(MAX(value),3) AS max_cpu_cores FROM abnormal_metrics WHERE service_name='geo' AND metric='container.cpu.usage' UNION ALL SELECT 'norm', ROUND(AVG(value),3), ROUND(MAX(value),3) FROM normal_metrics WHERE service_name='geo' AND metric='container.cpu.usage'", "claim": "Geo container CPU averages about 1.6 cores in the incident period versus about 0.003 cores normally, a plateau at 1.60."},
        {"kind": "metric", "sql": "SELECT time, metric, value FROM abnormal_metrics WHERE service_name='geo' AND metric IN ('container.cpu.usage','container.memory.working_set') ORDER BY time LIMIT 40", "claim": "Geo CPU ramps from about 1.0 to a flat 1.60 cores around 12:36 and stays there; working set rises about 9 MB."},
        {"kind": "metric", "sql": "SELECT p, service_name, ROUND(AVG(value),2) AS avg_cpu_time FROM (SELECT 'abn' AS p, service_name, value FROM abnormal_metrics_sum WHERE metric='container.cpu.time' UNION ALL SELECT 'norm', service_name, value FROM normal_metrics_sum WHERE metric='container.cpu.time') WHERE service_name IN ('geo','search','frontend') GROUP BY 1,2 ORDER BY 2,1", "claim": "Geo container CPU time is about 60x its normal level, while search and frontend rise only about 25%."},
        {"kind": "trace", "sql": "SELECT p, ROUND(quantile_cont(duration,0.95)/1e6,3) AS p95_ms, ROUND(quantile_cont(duration,0.99)/1e6,3) AS p99_ms FROM (SELECT 'abn' AS p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='geo' AND span_name='geo.Geo/Nearby' AND attr_span_kind='Server' GROUP BY 1", "claim": "Geo's own Nearby server spans are unchanged: p95 about 0.2 ms and p99 about 0.23 ms in both periods."}
      ]
    }
  ],
  "propagation": [
    {"from": "geo", "to": "search",
     "evidence": [{"kind": "trace", "sql": "SELECT p, COUNT(*) AS n, ROUND(quantile_cont(duration,0.99)/1e6,3) AS p99_ms, ROUND(MAX(duration)/1e6,3) AS max_ms FROM (SELECT 'abn' AS p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='search' AND span_name='geo.Geo/Nearby' AND attr_span_kind='Client' GROUP BY 1", "claim": "Search still calls geo on every request, but its client-side geo latency tail did not rise, so propagation is only plausible, not shown."}]},
    {"from": "search", "to": "frontend",
     "evidence": [{"kind": "trace", "sql": "SELECT p, service_name, span_name, ROUND(quantile_cont(duration,0.95)/1e6,3) AS p95_ms FROM (SELECT 'abn' AS p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE span_name='search.Search/Nearby' GROUP BY 1,2,3 ORDER BY 2,1", "claim": "Frontend calls search.Search/Nearby for every hotel search; its p95 is about 10 ms in both periods, so no measured impact reaches users."}]}
  ]
}
```

